<template>
  <div class="row-actions-menu" @click.stop>
    <q-btn
      flat
      dense
      round
      icon="more_vert"
      data-test="row-actions-trigger"
      :aria-label="$t('row_actions_menu')"
      aria-haspopup="menu"
      :aria-expanded="menuOpen ? 'true' : 'false'"
    >
      <q-menu
        v-model="menuOpen"
        anchor="bottom right"
        self="top right"
        :offset="[0, 4]"
        scroll-target="body"
        :no-refocus="true"
        role="menu"
        :aria-label="$t('row_actions_menu')"
      >
        <q-list dense class="compact-actions-list" role="menubar">
          <template v-for="(action, index) in visibleActions" :key="action.key">
            <!-- Separator before action if specified -->
            <q-separator v-if="action.separator && index > 0" role="separator" />

            <!-- Action Item -->
            <q-item
              clickable
              v-close-popup
              role="menuitem"
              :data-test="'row-action-' + action.key"
              :aria-label="$t(action.label)"
              @click="emitAction(action.key)"
            >
              <q-item-section v-if="action.icon" avatar class="list-avatar">
                <q-icon
                  :name="action.icon"
                  :color="isSvgIcon(action.icon) ? undefined : (action.color || 'grey-7')"
                  size="xs"
                  style="font-size: 14px"
                  :class="[
                    action.iconClass,
                    {
                      'svg-action-icon': isSvgIcon(action.icon) && !action.color && !action.iconClass,
                    },
                  ]"
                  aria-hidden="true"
                />
              </q-item-section>
              <q-item-section :class="action.color === 'negative' ? 'text-negative' : ''">
                {{ $t(action.label) }}
              </q-item-section>
            </q-item>
          </template>

          <!-- Empty state if no actions -->
          <q-item v-if="visibleActions.length === 0" disable aria-disabled="true">
            <q-item-section class="text-grey-6 text-center">
              No actions available
            </q-item-section>
          </q-item>
        </q-list>
      </q-menu>
    </q-btn>
  </div>
</template>

<script lang="ts">
import { ref, defineComponent, PropType } from 'vue';
import type { RowActionItem } from './types/table/unified-table';

export default defineComponent({
  name: 'RowActionsMenu',
  props: {
    /** Array of action configurations */
    actions: {
      type: Array as PropType<RowActionItem[]>,
      required: true,
    },
    /** Current row data (used for conditional visibility) */
    row: {
      type: Object as PropType<any>,
      required: true,
    },
  },
  emits: ['action'],
  setup() {
    return {
      menuOpen: ref(false),
    };
  },
  computed: {
    visibleActions(): RowActionItem[] {
      return this.actions.filter((action) => {
        if (!action.show) return true;
        return action.show(this.row);
      });
    },
  },
  methods: {
    // Check if icon is an SVG (starts with "img:")
    isSvgIcon(icon: string): boolean {
      return icon?.startsWith('img:') || false;
    },
    // Wrapper method for emitting action
    emitAction(key: string): void {
      // Close here rather than leaving it to `v-close-popup`. That directive
      // defers its close by a setTimeout so the @click can be emitted first, and
      // for an action whose `show` predicate reads the row — activate/deactivate —
      // the emit re-renders visibleActions and unmounts the clicked item before
      // the timeout runs. Quasar's getPortalProxy() then finds nothing from a
      // detached element and the menu stays open for good.
      this.menuOpen = false;
      this.$emit('action', key);
    },
  },
});
</script>

